package com.procurement.service;
import com.procurement.dto.ProcurementRequest; import com.procurement.entity.*; import com.procurement.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service public class ProcurementService { private final BookingRepository bookings; private final ProcurementRecordRepository records; private final NotificationService notifications; public ProcurementService(BookingRepository bookings,ProcurementRecordRepository records,NotificationService notifications){this.bookings=bookings;this.records=records;this.notifications=notifications;}
 @Transactional public ProcurementRecord arrive(Long id){Booking b=bookings.findById(id).orElseThrow();if(b.getStatus()!=BookingStatus.CONFIRMED)throw new IllegalArgumentException("Only CONFIRMED booking can arrive");ProcurementRecord r=records.findByBookingId(id).orElseGet(()->{ProcurementRecord x=new ProcurementRecord();x.setBooking(b);return x;});r.setStatus(ProcurementStatus.IN_PROGRESS);ProcurementRecord saved=records.save(r);notifications.create(b.getFarmer(),b,NotificationType.PROCUREMENT_STATUS,"Procurement started");return saved;}
 @Transactional public ProcurementRecord accept(Long id,ProcurementRequest req){Booking b=bookings.findById(id).orElseThrow();ProcurementRecord r=records.findByBookingId(id).orElseThrow(()->new IllegalArgumentException("Procurement record not started"));r.setProcuredQuantityQuintal(req.quantityQuintal());r.setStatus(ProcurementStatus.COMPLETED);r.setProcuredAt(LocalDateTime.now());b.setStatus(BookingStatus.COMPLETED);bookings.saveAndFlush(b);ProcurementRecord saved=records.save(r);notifications.create(b.getFarmer(),b,NotificationType.PROCUREMENT_STATUS,"Procurement completed");return saved;}
 @Transactional public ProcurementRecord reject(Long id,ProcurementRequest req){Booking b=bookings.findById(id).orElseThrow();ProcurementRecord r=records.findByBookingId(id).orElseThrow(()->new IllegalArgumentException("Procurement record not started"));r.setStatus(ProcurementStatus.REJECTED);r.setRejectionReason(req.rejectionReason());r.setProcuredAt(LocalDateTime.now());bookings.findById(id).ifPresent(x->{x.setStatus(BookingStatus.CANCELLED);bookings.saveAndFlush(x);});ProcurementRecord saved=records.save(r);notifications.create(b.getFarmer(),b,NotificationType.PROCUREMENT_STATUS,"Procurement rejected");return saved;}
 public ProcurementRecord status(Long id){return records.findByBookingId(id).orElseThrow(()->new IllegalArgumentException("Procurement record not found"));}
}
